//! CLI inbound port

use std::{path::PathBuf, str::FromStr};

use clap::{Parser, Subcommand};

use crate::{
    domain::{
        models::entity_ingestion::{
            DeclarationIngestionStage, EntityIngestionRequest, IngestionKey, MemberIngestionStage,
        },
        services::declaration_cleaning::DeclarationCleanerService,
        services::declaration_fetch::DeclarationFetcherService,
        services::declaration_loading::DeclarationLoaderService,
        services::declaration_resolution::DeclarationResolverService,
        services::entity_ingestion::{
            EntityFetcherService, EntityIngesterService, FetcherService, IngesterService,
        },
    },
    inbound::cli::config::{
        DataConfig, DeclarationFetcherConfig, DeclarationResolverConfig, FetcherConfig,
        LoaderConfig,
    },
    outbound::{ExposedDataPipeline, ExposedDatabase, ParliamentApiClient, WeldrsFunderScorer},
};

pub mod config;

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Refresh stored funder groups and direct evidence using the current pipeline policy.
    RefreshFunderGroups,
    /// Show the latest ingestion key and directory path.
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
    },
    /// Copy the latest raw capture into a new ingestion run.
    CopyLatestRaw {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Destination ingestion key. Defaults to a fresh UUID-v7.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Members {
        stage: String,
        #[arg(long)]
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// # Errors
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    match args.command {
        DataCommands::RefreshFunderGroups => {
            let config = DataConfig::from_env()?;
            let db = ExposedDatabase::new(&config.connection_string).await;
            let count = db.refresh_funder_groups().await?;
            println!("Refreshed funder groups: {count} identities");
        }
        DataCommands::Latest { config } => {
            let config = LoaderConfig::try_from(&config)?;
            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
                Some((path, key)) => {
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::CopyLatestRaw {
            config,
            ingestion_key,
        } => {
            let config = LoaderConfig::try_from(&config)?;
            let key = ingestion_key.unwrap_or_default();
            match ExposedDataPipeline::copy_latest_raw(&config.data_dir, key.clone()).await? {
                Some((path, source_key)) => {
                    println!("Source ingestion key: {source_key}");
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => match DeclarationIngestionStage::from_str(&stage)? {
            DeclarationIngestionStage::Fetch => {
                let config = DeclarationFetcherConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let api = ParliamentApiClient::new(config.batch_size)?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let fs = ExposedDataPipeline::new_with_ingestion_key(
                    &config.data_dir,
                    ingestion_key.unwrap_or_default(),
                )?;
                DeclarationFetcherService::new(db, api, fs)
                    .fetch_declarations()
                    .await?;
            }
            DeclarationIngestionStage::Resolve => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations resolve requires --ingestion-key")
                })?;
                let config = DeclarationResolverConfig::try_from(&config)?;
                let storage = ExposedDataPipeline::open_cleaned_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let scorer = WeldrsFunderScorer::new()?;
                let summary =
                    DeclarationResolverService::new(storage, scorer, config.candidate_budget)
                        .resolve_declarations()
                        .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Resolved declarations: {}",
                    std::path::absolute(config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("resolved/declarations")
                        .display()
                );
                println!("Observations: {}", summary.observations);
                println!("Funding occurrences: {}", summary.payments);
                println!("Pair decisions: {}", summary.pairs);
            }
            DeclarationIngestionStage::Load => {
                let ingestion_key = ingestion_key
                    .ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
                let config = LoaderConfig::try_from(&config)?;
                let data_config = DataConfig::from_env()?;
                let storage = ExposedDataPipeline::open_resolved_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let db = ExposedDatabase::new(&data_config.connection_string).await;
                let summary = DeclarationLoaderService::new(storage, db)
                    .load_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                match summary.outcome {
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::Imported => {
                        println!("Loaded declarations: {}", summary.declarations);
                    }
                    crate::domain::models::declaration_loading::DeclarationLoadOutcome::AlreadyLoaded => {
                        println!("Run already loaded. Declarations: {}", summary.declarations);
                    }
                }
                println!("Resolved identities: {}", summary.funders);
                println!("Funding occurrences: {}", summary.funding_entries);
            }
            DeclarationIngestionStage::Clean => {
                let ingestion_key = ingestion_key.ok_or_else(|| {
                    anyhow::anyhow!("declarations clean requires --ingestion-key")
                })?;
                let config = LoaderConfig::try_from(&config)?;
                let fs = ExposedDataPipeline::open_existing_declarations(
                    &config.data_dir,
                    ingestion_key.clone(),
                )?;
                let summary = DeclarationCleanerService::new(fs)
                    .clean_declarations()
                    .await?;
                println!("Ingestion key: {ingestion_key}");
                println!(
                    "Cleaned declarations: {}",
                    std::path::absolute(&config.data_dir)?
                        .join(ingestion_key.to_string())
                        .join("cleaned/declarations")
                        .display()
                );
                println!("Member partitions: {}", summary.member_partitions);
                println!("Declarations: {}", summary.declarations);
                println!("Funding entries: {}", summary.funding_entries);
                println!("Funder observations: {}", summary.funders);
            }
        },
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => {
            let stage = MemberIngestionStage::from_str(&stage)?;
            let ingestion_key = ingestion_key.unwrap_or_default();
            match stage {
                MemberIngestionStage::Fetch => {
                    let config = FetcherConfig::try_from(&config)?;
                    let api = ParliamentApiClient::new(config.batch_size)?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let service = FetcherService::new(fs, api);

                    let req = EntityIngestionRequest {};
                    service.fetch_members(&req).await?;
                }
                MemberIngestionStage::Load => {
                    let config = LoaderConfig::try_from(&config)?;
                    let data_config = DataConfig::from_env()?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let db = ExposedDatabase::new(&data_config.connection_string).await;
                    let service = IngesterService::new(fs, db);

                    service.load_members().await?;
                }
            }
        }
    }
    Ok(())
}

```sh
cargo run --package exposed --bin exposed -- data declarations resolve --config exposed/config/declaration-resolution-dev.yaml --ingestion-key "$ingestion_key"
```

The command writes observation identities, one attribution per funding occurrence,
statistical candidate decisions, and a manifest under `resolved/declarations`.
Company anchors use captured source numbers. The frozen native model supplies uncalibrated scores
for observations without eligible company IDs, including noncompanies. Initial
automatic links require exact names and complete usable addresses. Name-only and
fuzzy candidates remain for review, while named singletons receive separate
provisional identities. See the [resolution policy](docs/funder-resolution-design.md).

Load a resolved run into the searchable database after its members have been loaded:

```sh
cargo run --package exposed --bin exposed -- data declarations load --config exposed/config/declarations-dev.yaml --ingestion-key "$ingestion_key"
```

The loader includes declarations with no funding occurrences. It replaces only
declarations whose captured timestamps are newer, and an exact retry of an imported
run leaves the database unchanged. Keep the raw, cleaned, and resolved files for the
ingestion key because the loader validates and fingerprints all three stages. It
replaces each incoming funder's name, kind, company number, and searchable aliases
with that run's resolved values, including missing optional values. A shared
identity keeps its database ID, but its metadata and aliases reflect the last
accepted run. Declarations omitted from the run retain their funding entries.
After replacing entries, the loader removes funders and aliases that no remaining
funding entry references. These changes commit together or all roll back.

## View example declarations from the API

These standalone scripts require `bash`, `curl` and `jq`; no database, API key or
Python setup is needed. Run from the repository root:

```sh
# Declaration funder resolution

`exposed data declarations resolve --config CONFIG --ingestion-key UUID` reads the two cleaned declaration tables and writes identity, attribution, and candidate decisions. Rust owns the policy. The in-process SIMD scorer uses `weldrs` 0.2.2 to score feature profiles. No Python environment or subprocess is required. The command does not contact Companies House, install packages, or require a runtime database connection.

Resolution answers two independent questions. Observation resolution assigns an identity to each source role. Payment attribution chooses the source role used to report one funding occurrence. Resolving a donor does not make that donor the ultimate source of the payment.

## Input and address evidence

The cleaner replays retained source JSON and checks its existing raw projection. Supplemental addresses attach to the already checked source pointers. The raw Parquet projection and `CapturedFundingEntry` remain compatible with older captures.

At the root, `DonorPublicAddress`, `PayerPublicAddress`, and `UltimatePayerAddress` belong to their respective roles. Within a `Donors` group, `PublicAddress` belongs only to that nested donor. Root addresses never propagate into nested funding. Declaration-only names retain their root addresses without inventing a funding occurrence.

Cleaned observations retain `address_raw`, `address_normalized`, `address_source_field`, and `address_match_quality`. Normalization uses NFKC, lowercase, and collapsed whitespace. Absent values and blank strings remain distinct in raw evidence. Withheld, confidential, private, and not-provided placeholders have no usable normalized address.

`address_match_quality` is `unavailable`, `partial`, or `numbered_street`. The statistical rule requires a numeric house or building token and an explicit street designation. A postcode alone, a place name, or a named premise without a street number remains partial. Some valid international and named-premises addresses therefore require review.

The resolver rejects old member UUID artifacts with an instruction to capture a new ingestion run, then clean and resolve it. It checks unique IDs, member and declaration identities, source scopes, role ownership, and reciprocal observation links before scoring. Archived raw files are not needed to resolve a valid cleaned pair.

## Source-reported company anchors

A captured company number is accepted when it has eight ASCII alphanumeric characters and contains a digit. The parser trims outer ASCII whitespace and uppercases ASCII letters. It does not pad short values or remove internal punctuation. `SC012345` and `00527227` are accepted. `527227`, `NI 016363`, and overlong values are not repaired.

Only an explicit `Company` kind or absent kind permits an anchor. Other explicit kinds cannot use their company-number field as a company identity. The resulting key is `source-reported:companies-house:<NUMBER>`. Equal accepted numbers seed the same identity. This means agreement with source evidence, without registry verification.

Individuals, charities, unions, parties, trusts, and other organisations remain eligible for statistical candidates and provisional local identities. Missing donor metadata on payer roles is absence, never a disagreement. Explicit person and organisation kinds prevent an accepted link between incompatible components. `Other` and unfamiliar kinds remain unknown.

## Statistical candidates and acceptance

