}

fn decode_source(source: Value, fetched_at: DateTime<Utc>) -> Result<DecodedDeclaration, ApiError> {
    let source_json = source.to_string();
    let source: Interest = serde_json::from_value(source)?;
    let (version_index, latest) = source
        .versions
        .into_iter()
        .enumerate()
        .max_by_key(|(_, version)| (version.register.published_date, version.register.id))
        .ok_or_else(|| ApiError::ResponseError("declaration has no published version".into()))?;
    let pointer = format!("/versions/{version_index}/fields");
    let fields = latest.fields.unwrap_or_default();
    let mut funding = Vec::new();
    let mut pointers = Vec::new();
    funding_entries(&fields, &pointer, &mut funding, &mut pointers)?;
    let declaration = CapturedDeclaration::new(
        DeclarationId::new(source.id)?,
        source
            .parent_interest_id
            .map(DeclarationId::new)
            .transpose()?,
        source.category.id,
        source.category.name,
        latest.register.id,
        latest.register.published_date,
        latest.registration_date,
        funding,
        fetched_at,
        source_json,
    )?;
    Ok(DecodedDeclaration {
        declaration,
        fields,
        source_pointer: pointer,
        funding_source_pointers: pointers,
    })
}

//! Coordinates the checked declaration dataset with its atomic database import.

use crate::domain::{
    models::{declaration_loading::DeclarationLoadSummary, entity_ingestion::EntityIngestionError},
    repositories::declaration_loading::{DeclarationLoadRepository, DeclarationLoadStorage},
};

/// Loads resolved declarations into the current database projection.
pub struct DeclarationLoaderService<S, R> {
    storage: S,
    repository: R,
}

impl<S, R> DeclarationLoaderService<S, R> {
    /// Connects the resolved-run source to the database repository.
    #[must_use]
    pub const fn new(storage: S, repository: R) -> Self {
        Self {
            storage,
            repository,
        }
    }
}

impl<S: DeclarationLoadStorage, R: DeclarationLoadRepository> DeclarationLoaderService<S, R> {
    /// Reads and atomically loads one resolved declaration run.
    ///
    /// # Errors
    /// Returns source validation, stale-run, conflict, or database errors.
    pub async fn load_declarations(&self) -> Result<DeclarationLoadSummary, EntityIngestionError> {
        let load = self.storage.read_declaration_load().await?;
        self.repository.load_declarations(&load).await
    }
}
"}

