//! Atomic projection of the pipeline's grouping policy into stored membership and evidence.

use sqlx::{Postgres, Transaction};

use crate::domain::models::{
    entity_ingestion::EntityIngestionError,
    funder::FunderId,
    funder_grouping::{GroupingFunder, build_funder_groups},
};

use super::ExposedDatabase;

impl ExposedDatabase {
    /// Rebuilds grouping for every persisted identity without replaying ingestion artifacts.
    ///
    /// # Errors
    /// Returns database or grouping-policy errors. A failed refresh preserves the previous projection.
    pub async fn refresh_funder_groups(&self) -> Result<usize, EntityIngestionError> {
        let mut tx = self.pool().begin().await.map_err(db_error)?;
        lock_declaration_loader(&mut tx).await?;
        let count = replace_funder_groups(&mut tx).await?;
        tx.commit().await.map_err(db_error)?;
        Ok(count)
    }
}

pub(super) async fn lock_declaration_loader(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<(), EntityIngestionError> {
    sqlx::query!("SELECT pg_advisory_xact_lock(hashtext('exposed.declaration-loader'))")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    Ok(())
}

pub(super) async fn replace_funder_groups(
    tx: &mut Transaction<'_, Postgres>,
) -> Result<usize, EntityIngestionError> {
    let rows = sqlx::query!("SELECT id, funder_name FROM exposed.funders ORDER BY id")
        .fetch_all(&mut **tx)
        .await
        .map_err(db_error)?;
    let aliases = sqlx::query!("SELECT funder_id, funder_alias FROM exposed.funder_aliases ORDER BY funder_id, funder_alias")
        .fetch_all(&mut **tx).await.map_err(db_error)?;
    let mut by_id = std::collections::BTreeMap::<_, Vec<_>>::new();
    for alias in aliases {
        by_id
            .entry(alias.funder_id)
            .or_default()
            .push(alias.funder_alias);
    }
    let funders: Vec<_> = rows
        .into_iter()
        .map(|row| GroupingFunder {
            id: FunderId::new(row.id),
            name: row.funder_name,
            aliases: by_id.remove(&row.id).unwrap_or_default(),
        })
        .collect();
    let groups = build_funder_groups(&funders).map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_group_names")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_family_links")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    sqlx::query!("DELETE FROM exposed.funder_alias_groups")
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    for (id, group) in &groups.memberships {
        sqlx::query!(
            "INSERT INTO exposed.funder_alias_groups (funder_id, group_id) VALUES ($1, $2)",
            id.value(),
            group.value()
        )
        .execute(&mut **tx)
        .await
        .map_err(db_error)?;
    }
    for name in groups.preferred_names {
        sqlx::query!("INSERT INTO exposed.funder_group_names (group_id, preferred_name, family_key) VALUES ($1, $2, $3)", name.group_id.value(), name.preferred_name.as_str(), name.family_key)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.alias_links {
        sqlx::query!("INSERT INTO exposed.funder_alias_links (left_funder_id, right_funder_id, normalized_alias, left_alias, right_alias) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.normalized_alias, link.left_alias, link.right_alias)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    for link in groups.family_links {
        sqlx::query!("INSERT INTO exposed.funder_family_links (left_funder_id, right_funder_id, family_key, left_name, right_name) VALUES ($1, $2, $3, $4, $5)", link.left_funder_id.value(), link.right_funder_id.value(), link.family_key, link.left_name, link.right_name)
            .execute(&mut **tx).await.map_err(db_error)?;
    }
    Ok(groups.memberships.len())
}

fn db_error(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(error.to_string())
}
use super::{
    AttributionBasis, AttributionDecision, AttributionIssue, BTreeSet, FunderObservationId,
    FunderRole, Payment, PaymentAttribution, ResolutionInput, UnavailableReason,
};
use super::{identity::company, input::is_root};

pub(super) fn attribute(input: &ResolutionInput, payment: &Payment) -> PaymentAttribution {
    let mut issues = Vec::new();
    if let Some(id) = &payment.ultimate_payer_funder_id {
        if payment.is_ultimate_payer_different == Some(false) {
            issues.push(AttributionIssue::ExplicitUltimatePayerWithParentPayerSameFlag);
        }
        let decision = local_selection(
            input,
            id,
            AttributionBasis::ExplicitUltimatePayer,
            UnavailableReason::ExplicitUltimatePayerUnavailable,
        );
        return PaymentAttribution {
            funding_entry_id: payment.funding_entry_id.clone(),
            decision,
            issues,
        };
    }
    let decision = match payment.is_ultimate_payer_different {
        Some(true) => unavailable(UnavailableReason::DifferentUltimatePayerUnnamed),
        Some(false) => parent_selection(input, payment),
        None => match (&payment.donor_funder_id, &payment.payer_funder_id) {
            (Some(id), _) => local_selection(
                input,
                id,
                AttributionBasis::Donor,
                UnavailableReason::DonorUnavailable,
            ),
            (None, Some(id)) => local_selection(
                input,
                id,
                AttributionBasis::Payer,
                UnavailableReason::PayerUnavailable,
            ),
            (None, None) => unavailable(UnavailableReason::NoSupportedAttribution),
        },
    };
    PaymentAttribution {
        funding_entry_id: payment.funding_entry_id.clone(),
        decision,
        issues,
    }
}
fn usable(input: &ResolutionInput, id: &FunderObservationId) -> bool {
    let observation = &input.observations[id];
    observation.name_normalized.is_some() || company(observation).is_some()
}
const fn unavailable(reason: UnavailableReason) -> AttributionDecision {
    AttributionDecision::Unavailable {
        unavailable_reason: reason,
    }
}
fn local_selection(
    input: &ResolutionInput,
    id: &FunderObservationId,
    basis: AttributionBasis,
    reason: UnavailableReason,
) -> AttributionDecision {
    if usable(input, id) {
        AttributionDecision::Selected {
            selected_funder_id: id.clone(),
            attribution_basis: basis,
            selected_parent_declaration_id: None,
        }
    } else {
        unavailable(reason)
    }
}
fn parent_selection(input: &ResolutionInput, payment: &Payment) -> AttributionDecision {
    if parent_cycle(input, payment) {
        return unavailable(UnavailableReason::ParentCycle);
    }
    let Some(parent) = payment.parent_declaration_id else {
        return unavailable(UnavailableReason::ParentEvidenceUnavailable);
    };
    let candidates = input
        .observations
        .values()
        .filter(|observation| {
            observation.member_id == payment.member_id
                && observation.declaration_id == parent
                && observation.role == FunderRole::Payer
                && is_root(&observation.source_pointer)
        })
        .collect::<Vec<_>>();
    match candidates.as_slice() {
        [payer] if usable(input, &payer.funder_id) => AttributionDecision::Selected {
            selected_funder_id: payer.funder_id.clone(),
            attribution_basis: AttributionBasis::ParentPayer,
