            declarations,
            exclusions,
            omissions,
            receipts,
            artifacts: BTreeMap::new(),
            content_sha256,
            content_changed,
            captured_at: Utc::now(),
        };
        let publication = self.storage.seal_snapshot(snapshot).await?;
        self.publish(&run, &publication, content_changed).await.map_err(|error| invalid(&format!("sealed declaration run {run}; recover with declarations sync --resume {run}: {error}")))?;
        Ok(run)
    }

    async fn acquire(
        &self,
        mode: DeclarationSyncMode,
        scope: &[MemberId],
        window: &DiscoveryWindow,
        mut declarations: BTreeMap<DeclarationId, OwnedDeclaration>,
    ) -> Result<AcquiredDeclarations, EntityIngestionError> {
        let mut receipts = Vec::new();
        let mut exclusions = BTreeMap::new();
        let mut omissions = Vec::new();
        match mode {
            DeclarationSyncMode::Daily => {
                let (discovered, pages) = self.source.discover(window).await?;
                receipts.extend(pages);
                for (id, owner) in discovered {
                    if declarations
                        .get(&id)
                        .is_some_and(|previous| previous.member != owner)
                    {
                        return Err(invalid(
                            "discovery registrant disagrees with retained declaration ownership",
                        ));
                    }
                    if !scope.contains(&owner) {
                        exclusions.insert(id, owner);
                        continue;
                    }
                    let (record, pages) = self.source.hydrate(id).await?;
                    receipts.extend(pages);
                    match record {
                        Some(record) => {
                            if record.member != owner || record.declaration.id() != id {
                                return Err(invalid(
                                    "hydration ownership or declaration identity disagrees with discovery",
                                ));
                            }
                            merge_record(&mut declarations, record)?;
                        }
                        None => omissions.push(id),
                    }
                }
            }
            DeclarationSyncMode::Reconcile => {
                let mut observed = BTreeSet::new();
                for member in scope {
                    let (records, pages) = self.source.capture_member(*member).await?;
                    receipts.extend(pages);
                    for record in records {
                        if record.member != *member || !observed.insert(record.declaration.id()) {
                            return Err(invalid(
                                "complete capture has mismatched ownership or duplicate declaration IDs",
                            ));
                        }
                        merge_record(&mut declarations, record)?;
                    }
                }
                omissions.extend(
                    declarations
                        .keys()
                        .filter(|id| !observed.contains(id))
                        .copied(),
                );
            }
        }
        Ok(AcquiredDeclarations {
            declarations,
            receipts,
            exclusions,
            omissions,
        })
    }

    async fn hydrate_parents(
        &self,
        acquired: &mut AcquiredDeclarations,
    ) -> Result<(), EntityIngestionError> {
        let declarations = &mut acquired.declarations;
        let receipts = &mut acquired.receipts;
        let mut checked_parents = BTreeSet::new();
        loop {
            let mut missing = BTreeMap::<_, BTreeSet<_>>::new();
            for record in declarations.values() {
                if let Some(id) = record.declaration.parent_id()
                    && !declarations.contains_key(&id)
                    && !checked_parents.contains(&id)
                {
                    missing.entry(id).or_default().insert(record.member);
                }
            }
            if missing.is_empty() {
                break;
            }
            for (id, members) in missing {
                checked_parents.insert(id);
                let (record, pages) = self.source.hydrate(id).await?;
                receipts.extend(pages);
                match record {
                    Some(record) if members.contains(&record.member) => {
                        merge_record(declarations, record)?;
                    }
                    Some(_) | None => {}
                }
            }
        }
        Ok(())
    }

    /// Continues sealed evidence without reacquiring or modifying source records.
    ///
    /// # Errors
    /// Rejects unsealed, changed, or stale evidence.
    pub async fn resume(&self, run: IngestionKey) -> Result<IngestionKey, EntityIngestionError> {
        let (snapshot, publication) = self.storage.open_sealed_run(&run)?;
        if snapshot.run != run.uuid() {
            return Err(invalid("resume manifest belongs to another run"));
        }
        self.publish(&run, &publication, snapshot.content_changed).await.map_err(|error| invalid(&format!("sealed declaration run {run}; recover with declarations sync --resume {run}: {error}")))?;
        Ok(run)
    }

    async fn publish(
        &self,
        run: &IngestionKey,
        publication: &PreparedPublication,
        changed: bool,
    ) -> Result<(), EntityIngestionError> {
        let load = if changed {
            Some(self.storage.prepare_load(run).await?)
        } else {
            None
        };
        self.repository
            .publish_sync(publication, load.as_ref())
            .await?;
        Ok(())
    }
}

fn discovery_window(
    base: Option<&CompleteDeclarationSnapshot>,
        Ok(summary)
    }

    pub(super) async fn publish_declaration_sync(
        &self,
        publication: &crate::domain::models::declaration_sync::PreparedPublication,
        load: Option<&DeclarationLoad>,
    ) -> Result<bool, EntityIngestionError> {
        use crate::domain::services::declaration_sync::digest;
        let manifest_bytes = fs::read(&publication.manifest_path).map_err(read_error)?;
        if digest(&manifest_bytes) != publication.manifest_sha256 {
            return Err(data_error("sealed capture changed before publication"));
        }
        let snapshot: crate::domain::models::declaration_sync::CompleteDeclarationSnapshot =
            serde_json::from_slice(&manifest_bytes).map_err(db_error)?;
        if snapshot.run != publication.run
            || snapshot.expected_revision != publication.expected_revision
            || snapshot.window.through != publication.coverage_date
            || snapshot.content_changed != load.is_some()
        {
            return Err(data_error("publication disagrees with its sealed manifest"));
        }
        if load.is_some_and(|load| load.ingestion_key.uuid() != publication.run) {
            return Err(data_error("projection belongs to another capture"));
        }
        let fingerprint = digest(
            format!(
                "{}:{}",
                publication.manifest_sha256,
                load.map_or("unchanged", |load| load.fingerprint.as_str())
            )
            .as_bytes(),
        );
        let mut tx = self.pool().begin().await.map_err(db_error)?;
        super::funder_grouping::lock_declaration_loader(&mut tx).await?;
        if let Some(existing) = sqlx::query!(
            "SELECT fingerprint FROM exposed.declaration_sync_runs WHERE ingestion_key = $1",
            publication.run
        )
        .fetch_optional(&mut *tx)
        .await
        .map_err(db_error)?
        {
            if existing.fingerprint != fingerprint {
                return Err(data_error(
                    "committed sync run has different evidence or projection",
                ));
            }
            tx.commit().await.map_err(db_error)?;
            return Ok(false);
        }
        let revision = sqlx::query_scalar!("SELECT run.revision FROM exposed.declaration_sync_head head JOIN exposed.declaration_sync_runs run USING (ingestion_key) WHERE head.singleton").fetch_optional(&mut *tx).await.map_err(db_error)?.unwrap_or(0);
        if revision != publication.expected_revision {
            return Err(data_error(
                "stale declaration publication base; start a new capture from the committed head",
            ));
        }
        if load.is_none() {
            let committed_content = sqlx::query_scalar!("SELECT run.content_sha256 FROM exposed.declaration_sync_head head JOIN exposed.declaration_sync_runs run USING (ingestion_key) WHERE head.singleton").fetch_optional(&mut *tx).await.map_err(db_error)?;
            if committed_content.as_deref() != Some(snapshot.content_sha256.as_str()) {
                return Err(data_error(
                    "unchanged publication content differs from the committed snapshot",
                ));
            }
        }
        let scope = snapshot
            .scope
            .iter()
            .map(|member| i32::try_from(member.value()).map_err(db_error))
            .collect::<Result<Vec<_>, _>>()?;
        let stored_scope = sqlx::query_scalar!("SELECT parliament_member_id FROM exposed.members WHERE parliament_member_id = ANY($1) ORDER BY parliament_member_id FOR KEY SHARE", &scope).fetch_all(&mut *tx).await.map_err(db_error)?;
        if stored_scope != scope {
            return Err(data_error(
                "a member in the sealed declaration scope is no longer stored",
            ));
        }
        if let Some(load) = load {
            self.apply_declaration_load(&mut tx, load).await?;
        } else if revision == 0 {
            return Err(data_error(
                "initial sync publication requires a complete projection",
            ));
        }
        let coverage_date = time::Date::from_calendar_date(
            chrono::Datelike::year(&publication.coverage_date),
            time::Month::try_from(
                u8::try_from(chrono::Datelike::month(&publication.coverage_date))
                    .map_err(db_error)?,
            )
            .map_err(db_error)?,
            u8::try_from(chrono::Datelike::day(&publication.coverage_date)).map_err(db_error)?,
        )
        .map_err(db_error)?;
        let revision = revision
            .checked_add(1)
            .ok_or_else(|| data_error("publication revision overflow"))?;
        let path = publication
            .manifest_path
            .to_str()
            .ok_or_else(|| data_error("manifest path is not UTF-8"))?;
        sqlx::query!("INSERT INTO exposed.declaration_sync_runs (ingestion_key, fingerprint, content_sha256, revision, manifest_path, manifest_sha256, coverage_date) VALUES ($1, $2, $3, $4, $5, $6, $7)", publication.run, fingerprint, snapshot.content_sha256, revision, path, publication.manifest_sha256, coverage_date).execute(&mut *tx).await.map_err(db_error)?;
        sqlx::query!("INSERT INTO exposed.declaration_sync_head (singleton, ingestion_key) VALUES (true, $1) ON CONFLICT (singleton) DO UPDATE SET ingestion_key = EXCLUDED.ingestion_key", publication.run).execute(&mut *tx).await.map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
        Ok(true)
    }
}
//! Ports for complete declaration capture and atomic publication.
use crate::domain::models::{
    declaration_ingestion::DeclarationId,
    declaration_loading::DeclarationLoad,
    declaration_sync::{
        CompleteDeclarationSnapshot, DeclarationSyncHead, DiscoveryReceipt, DiscoveryWindow,
        OwnedDeclaration, PreparedPublication,
    },
    entity_ingestion::{EntityIngestionError, IngestionKey},
    parliament_member::MemberId,
};
use std::{collections::BTreeMap, path::Path};

/// Declaration-only Parliament acquisition.
pub trait DeclarationSyncSource: Send + Sync {
    /// Exact source policy recorded in each manifest.
    fn policy(&self) -> String;
    /// Discovers IDs. Filtered payloads are never complete replacement records.
    fn discover(
        &self,
        window: &DiscoveryWindow,
    ) -> impl Future<
        Output = Result<
            (BTreeMap<DeclarationId, MemberId>, Vec<DiscoveryReceipt>),
            EntityIngestionError,
        >,
    > + Send;
    /// Hydrates one ID without publication/update filters.
    fn hydrate(
        &self,
        id: DeclarationId,
    ) -> impl Future<
        Output = Result<(Option<OwnedDeclaration>, Vec<DiscoveryReceipt>), EntityIngestionError>,
    > + Send;
    /// Complete declaration history for an explicit member, without member metadata.
    fn capture_member(
        &self,
        member: MemberId,
    ) -> impl Future<
        Output = Result<(Vec<OwnedDeclaration>, Vec<DiscoveryReceipt>), EntityIngestionError>,
    > + Send;
}

/// Database ownership and publication boundary.
pub trait DeclarationSyncRepository: Send + Sync {
    /// Reads the sole committed head.
    fn sync_head(
        &self,
    ) -> impl Future<Output = Result<Option<DeclarationSyncHead>, EntityIngestionError>> + Send;
    /// Existing source declaration IDs, used to reject an incomplete initial baseline.
    fn projected_declaration_ids(
        &self,
    ) -> impl Future<Output = Result<Vec<DeclarationId>, EntityIngestionError>> + Send;
    /// Publishes projection and coverage together. A missing load means content is unchanged.
    fn publish_sync(
        &self,
        publication: &PreparedPublication,
        load: Option<&DeclarationLoad>,
    ) -> impl Future<Output = Result<bool, EntityIngestionError>> + Send;
}

/// Durable immutable capture storage and existing interpretation pipeline.
pub trait DeclarationSyncStorage: Send + Sync {
    /// Loads and checks committed evidence and all raw artifact digests.
    ///
    /// # Errors
    /// Rejects missing, incomplete, or modified evidence.
    fn read_snapshot(
        &self,
        path: &Path,
        digest: Option<&str>,
    ) -> Result<CompleteDeclarationSnapshot, EntityIngestionError>;
    /// Publishes raw partitions before sealing the complete capture manifest.
    fn seal_snapshot(
        &self,
        snapshot: CompleteDeclarationSnapshot,
    ) -> impl Future<Output = Result<PreparedPublication, EntityIngestionError>> + Send;
    /// Opens an explicitly resumed run and its checked publication request.
    ///
    /// # Errors
    /// Rejects missing, incomplete, or modified sealed evidence.
    fn open_sealed_run(
        &self,
        run: &IngestionKey,
    ) -> Result<(CompleteDeclarationSnapshot, PreparedPublication), EntityIngestionError>;
    /// Reuses validated completed stage outputs, or runs full cleaning and resolution.
    fn prepare_load(
        &self,
        run: &IngestionKey,
    ) -> impl Future<Output = Result<DeclarationLoad, EntityIngestionError>> + Send;
}
"}

